-- TEST DATA for the lot trace and recall workspace. NOT a migration - run by hand, removed by delete.sql.
-- Every row carries data._test_batch = 'RECALL-TEST', every lot starts TEST- or is 9901 / 9902 (no real lot code
-- has a day above 366), and every product and customer starts with TEST.
-- Retention (FRM-703) and release (FRM-701) go in as DRAFTS: submitted ones would tick off the weekly
-- retention and release review reminders on the verification schedule. Test FRM-801 dispatches are dated
-- before the real one of 2026-10-01, so the dispatch review is not affected either.

begin;

do $guard$
begin
  if exists (select 1 from public.sop_document_responses where data->>'_test_batch' = 'RECALL-TEST') then
    raise exception 'Recall test data is already there - run delete.sql first.';
  end if;
end $guard$;

insert into public.sop_document_responses
  (document_id, form_number, form_revision, data, status, created_by, created_at, submitted_at, submitted_by)
select d.id, d.sop_number, d.revision, v.data, v.status, '5eea644d-d8d3-4ad3-a55a-ef391334432d'::uuid, v.at,
       case when v.status = 'submitted' then v.at end, case when v.status = 'submitted' then '5eea644d-d8d3-4ad3-a55a-ef391334432d'::uuid end
from (values
