  ('FRM-701', 'draft', '2026-09-23T14:00:00Z'::timestamptz, $j${"product_name": "TEST Rum Cake Original", "lot_code": "9901", "date_produced": "2026-09-22", "quantity_released": "120 units", "customer": "TEST Island Treats LLC", "checks": [{"result": "pass", "note": ""}, {"result": "pass", "note": ""}, {"result": "pass", "note": ""}, {"result": "pass", "note": ""}, {"result": "pass", "note": ""}, {"result": "pass", "note": ""}, {"result": "pass", "note": ""}, {"result": "pass", "note": ""}], "decision": "RELEASED — may be shipped, collected or transferred", "release_date": "2026-09-23", "release_notes": "TEST DATA", "_test_batch": "RECALL-TEST"}$j$::jsonb),
