join public.sop_documents d on d.sop_number = v.form and d.type = 'form' and d.status in ('active', 'draft');

do $verify$
begin
  if (select count(*) from public.sop_document_responses where data->>'_test_batch' = 'RECALL-TEST') <> 12 then
    raise exception 'Expected 12 test rows.';
  end if;
end $verify$;

commit;
